def get_channel_starting_with_external():
    channels = get_channels()
    for channel in channels:
        if channel.startswith("External"):
            return channel
    return None

external_channel = get_channel_starting_with_external()
if external_channel:
    add_user_to_channel("Charlie", external_channel)
else:
    raise ValueError("No channel starting with 'External' found")
